// Build fast lookup tables on global window object
declare global {
  interface Window {
    __CURRICULUM?: CurriculumItem[]
    __CURRICULUM_RANKS?: Record<string, number>
    __curriculumNavInitialized?: boolean
  }
}

const ranks: Record<string, number> = {};
CURRICULUM_DATA.forEach((item, idx) => {
  ranks[item.filePath] = idx;
  ranks[item.slug] = idx;
});

window.__CURRICULUM = CURRICULUM_DATA;
window.__CURRICULUM_RANKS = ranks;

function getSiteBasePath(): string {
  const base = document.body?.dataset?.basepath ?? "";
  if (!base || base === "/") return "";
  return base.endsWith("/") ? base.slice(0, -1) : base;
}

function normalizeSlug(slug: string): string {
  let s = slug.replace(/^\/+|\/+$/g, "");
  // Remove baseUrl prefix if present in location.pathname
  const base = getSiteBasePath().replace(/^\/+|\/+$/g, "");
  if (base && s.startsWith(base)) {
    s = s.slice(base.length).replace(/^\/+/, "");
  }
  if (s.endsWith("/index")) s = s.slice(0, -6);
  if (s.endsWith(".html")) s = s.slice(0, -5);
  return s.toLowerCase();
}

function renderCurriculumPager() {
  // Remove existing pager if present
  document.querySelector(".curriculum-pager-wrapper")?.remove();

  const currentRawSlug = document.body?.dataset?.slug ?? window.location.pathname;
  const currentSlug = normalizeSlug(currentRawSlug);

  // If on index or 404, don't show lesson pagination
  if (!currentSlug || currentSlug === "index" || currentSlug === "404") {
    return;
  }

  // Find index in curriculum
  let currentIndex = CURRICULUM_DATA.findIndex((item) => normalizeSlug(item.slug) === currentSlug);

  // Fallback: match by filename
  if (currentIndex === -1) {
    const currentFileName = currentSlug.split("/").pop();
    currentIndex = CURRICULUM_DATA.findIndex((item) => {
      const itemFileName = normalizeSlug(item.slug).split("/").pop();
      return itemFileName === currentFileName;
    });
  }

  if (currentIndex === -1) {
    return;
  }

  const total = CURRICULUM_DATA.length;
  const currentItem = CURRICULUM_DATA[currentIndex];
  const prevItem = currentIndex > 0 ? CURRICULUM_DATA[currentIndex - 1] : null;
  const nextItem = currentIndex < total - 1 ? CURRICULUM_DATA[currentIndex + 1] : null;

  const basePath = getSiteBasePath();

  // Create Pager Container
  const wrapper = document.createElement("div");
  wrapper.className = "curriculum-pager-wrapper";

  const progressPct = Math.round(((currentIndex + 1) / total) * 100);

  let html = `
    <div class="curriculum-pager-meta">
      <div class="pager-meta-badge">
        <span class="badge-dot"></span>
        <span class="badge-text">Learning Path</span>
      </div>
      <div class="pager-meta-counter">Topic <strong>${currentIndex + 1}</strong> of <strong>${total}</strong> (${progressPct}%)</div>
    </div>
    <div class="pager-progress-bar">
      <div class="pager-progress-fill" style="width: ${progressPct}%"></div>
    </div>
    <nav class="curriculum-pager" aria-label="Curriculum Topic Navigation">
  `;

  if (prevItem) {
    const prevUrl = `${basePath}/${prevItem.slug}`;
    html += `
      <a class="pager-card pager-prev" href="${prevUrl}" rel="prev">
        <div class="pager-card-direction">
          <svg viewBox="0 0 24 24" width="15" height="15" stroke="currentColor" stroke-width="2.5" fill="none"><polyline points="15 18 9 12 15 6"></polyline></svg>
          <span>Previous Lesson</span>
        </div>
        <div class="pager-card-title">${prevItem.title}</div>
      </a>
    `;
  } else {
    const homeUrl = `${basePath}/`;
    html += `
      <a class="pager-card pager-prev pager-home" href="${homeUrl}">
        <div class="pager-card-direction">
          <svg viewBox="0 0 24 24" width="15" height="15" stroke="currentColor" stroke-width="2.5" fill="none"><polyline points="15 18 9 12 15 6"></polyline></svg>
          <span>Curriculum Start</span>
        </div>
        <div class="pager-card-title">Interview Playbook Overview</div>
      </a>
    `;
  }

  if (nextItem) {
    const nextUrl = `${basePath}/${nextItem.slug}`;
    html += `
      <a class="pager-card pager-next" href="${nextUrl}" rel="next">
        <div class="pager-card-direction">
          <span>Next Lesson</span>
          <svg viewBox="0 0 24 24" width="15" height="15" stroke="currentColor" stroke-width="2.5" fill="none"><polyline points="9 18 15 12 9 6"></polyline></svg>
        </div>
        <div class="pager-card-title">${nextItem.title}</div>
      </a>
    `;
  } else {
    html += `
      <div class="pager-card pager-next pager-complete">
        <div class="pager-card-direction">
          <span>Curriculum Complete</span>
          <svg viewBox="0 0 24 24" width="15" height="15" stroke="currentColor" stroke-width="2.5" fill="none"><polyline points="20 6 9 17 4 12"></polyline></svg>
        </div>
        <div class="pager-card-title">Congratulations! All Topics Mastered</div>
      </div>
    `;
  }

  html += `</nav>`;
  wrapper.innerHTML = html;

  // Insert before .page-footer or at the end of .center
  const centerEl = document.querySelector(".center");
  const pageFooter = document.querySelector(".center > .page-footer") || document.querySelector(".center > hr:last-of-type");

  if (pageFooter && pageFooter.parentNode) {
    pageFooter.parentNode.insertBefore(wrapper, pageFooter);
  } else if (centerEl) {
    centerEl.appendChild(wrapper);
  }
}

// Initialize SPA events and keyboard navigation
if (!window.__curriculumNavInitialized) {
  window.__curriculumNavInitialized = true;

  document.addEventListener("nav", () => {
    renderCurriculumPager();
  });

  // Keyboard navigation: Alt + ArrowLeft / Alt + ArrowRight
  window.addEventListener("keydown", (e: KeyboardEvent) => {
    const target = e.target as HTMLElement | null;
    if (target && (target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable)) {
      return;
    }
    if (e.altKey && e.key === "ArrowRight") {
      const nextLink = document.querySelector<HTMLAnchorElement>(".pager-next");
      if (nextLink && nextLink.href) {
        nextLink.click();
      }
    } else if (e.altKey && e.key === "ArrowLeft") {
      const prevLink = document.querySelector<HTMLAnchorElement>(".pager-prev");
      if (prevLink && prevLink.href) {
        prevLink.click();
      }
    }
  });
}

export default "";
